'use strict';
const StudioResearchView={render(ctx){
 const {app,esc,data,heading,bind,go,sources}=ctx,hash=location.hash.split('?')[0],parts=hash.split('/'),type=parts[1],id=parts[2],params=new URLSearchParams(location.hash.split('?')[1]||'');
 const saved=history.state?.researchReturn||'#research';
 const link=(url,label)=>/^https:\/\//.test(url||'')?'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+' ↗</a>':'';
 const fields=pairs=>'<dl>'+pairs.filter(x=>x[1]!==null&&x[1]!==undefined&&x[1]!=='').map(([k,v])=>'<dt><b>'+esc(k)+'</b></dt><dd>'+esc(String(v))+'</dd>').join('')+'</dl>';
 if(type&&id){const item=(type==='journal'?data.journals:type==='article'?data.articles:[]).find(x=>x.id===id);if(!item){app.innerHTML='<h1>Research record not found</h1><a href="#research" data-studio-go>Back to research</a>';bind();return;}
 let details=fields([['Review status',item.editorialStatus||item.credentialStatus],['Review depth',item.reviewLabel],['Year',item.year],['Authors',Array.isArray(item.authors)?item.authors.join(', '):'Not yet checked'],['Journal',item.journalTitle],['Participants',item.population],['Design',item.studyDesign],['Limits',item.limitation],['Relationship to activities',item.relationship],['Corrections',item.correctionStatus],['Verification',item.verificationNote],['Source checked',item.sourceCheckedDate||item.verificationDate]]);
 if(type==='journal'){details+=fields([['Publisher',item.publisher],['ISSN',item.issn],['Credential status',item.credentialStatus]]);if(item.metric){details+='<section class="studio-metric"><h2>Publisher-reported metric</h2>'+fields([['Metric',item.metric.name],['Value',item.metric.value],['Metric year',item.metric.year],['Provenance',item.metric.provenance]])+link(item.metric.source,'Metric source')+'</section>';}details+='<h2>Indexing sources</h2>'+((item.indexing||[]).map(x=>'<p><b>'+esc(x.database)+'</b> · '+esc(x.provenance||'')+' '+link(x.source,'Check source')+'</p>').join('')||'<p>Indexing has not yet been verified.</p>');}
 const related=(item.tags||[]).includes('reading')|| (item.tags||[]).includes('dyslexia')?'short-words-v2':'everyday-words-v2';
 app.innerHTML=heading('RESEARCH',item.title||item.name,'Source details and the limits of what has been reviewed')+'<article class="studio-reading"><p>'+esc(item.summary||item.scope||'This reference has not yet received an abstract review.')+'</p>'+details+'<p>'+link(item.url||item.sourceUrl,'Original source')+' '+link(item.correctionUrl,'Published correction')+' '+link(item.fullTextUrl,'Free full text')+' '+link(item.abstractSourceUrl,'Abstract source')+'</p>'+(type==='article'?'<aside class="studio-notice"><p>This source relates to teaching principles. It does not evaluate our game or course.</p><a href="#course/'+related+'" data-studio-course="'+related+'">Explore a related course</a></aside>':'')+'<a id="studioResearchBack" href="'+esc(saved)+'">Back to research results</a></article>';bind();app.querySelector('#studioResearchBack').onclick=e=>{e.preventDefault();go(saved);};return;}
 const filters={q:params.get('q')||'',topic:params.get('topic')||'',review:params.get('review')||'',design:params.get('design')||'',year:params.get('year')||'',language:params.get('language')||'',access:params.get('access')||'',age:params.get('age')||''};
 const select=(id,key,label,options)=>'<label>'+label+'<select id="'+id+'" data-research-filter="'+key+'"><option value="">All</option>'+options.map(([v,t])=>'<option value="'+esc(v)+'" '+(filters[key]===v?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select></label>';
 const unique=key=>[...new Set(data.articles.flatMap(a=>Array.isArray(a[key])?a[key]:a[key]?[String(a[key])]:[]))].filter(x=>x!=='unknown').sort().map(x=>[x,x]);
 app.innerHTML=heading('RESEARCH','Understand the evidence','Find relevant studies and see what was actually reviewed.')+'<p><a href="#review?kind=article" data-studio-go>Review the research records →</a></p><p class="studio-notice">These are source notes awaiting independent editorial review. A journal metric is not a quality rating for an individual study. Unknown information is not inferred.</p><div class="studio-research-filters"><label>Search research<input id="studioResearchSearch" type="search" value="'+esc(filters.q)+'" placeholder="Reading, language or AAC"></label>'+select('studioTopicFilter','topic','Topic',unique('tags'))+'<details class="studio-filter-more"><summary>More filters · review depth, year, age and access</summary><div class="studio-research-filters">'+select('studioReviewFilter','review','Review depth',[['abstract-only','Abstract read'],['full-text','Full text reviewed']])+select('studioDesignFilter','design','Study type',[['review','Reviews and meta-analyses'],['trial','Trials']])+select('studioYearFilter','year','Publication year',unique('year'))+select('studioLanguageFilter','language','Teaching language',[...unique('language'),['unknown','Not reported / not checked']])+select('studioAccessFilter','access','Full-text access',[['open','Open access reported'],['restricted','Restricted access verified'],['unknown','Not checked']])+select('studioAgeFilter','age','Participant age',[...unique('ageGroups'),['unknown','Not reported / not checked']])+'</div></details></div><button id="studioResearchClear" class="secondary">Clear filters</button><p id="studioResearchCount" role="status"></p><div id="studioArticles"></div><h2>Journal directory</h2><div class="studio-grid">'+data.journals.map(j=>'<article class="studio-card"><h3><a href="#research/journal/'+j.id+'" data-research-detail>'+esc(j.title||j.name)+'</a></h3><p>'+esc(j.scope||'Educational research')+'</p><small>'+esc(j.credentialStatus||'pending-verification')+'</small></article>').join('')+'</div><details><summary>Guidance and professional resources</summary>'+sources.map(s=>'<p>'+link(s.url,s.title)+' — '+esc(s.note)+'</p>').join('')+'</details>';
 function renderResults(){const found=data.articles.filter(a=>StudioCore.matches(a,filters));app.querySelector('#studioResearchCount').textContent=found.length+' of '+data.articles.length+' references';app.querySelector('#studioArticles').innerHTML=found.map(a=>'<article class="studio-research-card"><small>'+esc(a.reviewLabel||'Reference discovered; abstract not reviewed')+' · '+esc(a.editorialStatus||'Draft')+'</small><h2><a href="#research/article/'+a.id+'" data-research-detail>'+esc(a.title)+'</a></h2><p>'+esc(a.summary||'Abstract review pending. Open the original source for details.')+'</p></article>').join('')||'<p>No references match these filters. Clear filters or choose a broader topic.</p>';bind();app.querySelectorAll('[data-research-detail]').forEach(a=>a.onclick=e=>{if(e.ctrlKey||e.metaKey)return;e.preventDefault();const returnTo=location.hash;history.pushState({...history.state,researchReturn:returnTo},'',location.pathname+a.getAttribute('href'));StudioResearchView.render(ctx);});}
 function update(){filters.q=app.querySelector('#studioResearchSearch').value;app.querySelectorAll('[data-research-filter]').forEach(el=>filters[el.dataset.researchFilter]=el.value||'');const p=new URLSearchParams();for(const[k,v]of Object.entries(filters))if(v)p.set(k,v);history.replaceState({...history.state,researchReturn:'#research'+(p.size?'?'+p.toString():'')},'',location.pathname+'#research'+(p.size?'?'+p.toString():''));renderResults();}
 app.querySelector('#studioResearchSearch').oninput=update;app.querySelectorAll('select').forEach(el=>el.onchange=update);app.querySelector('#studioResearchClear').onclick=()=>go('#research');renderResults();
}};
